commands:
cd <WORKSPACE>/smb-infrastructure-dashboard
agent-browser eval "(() => {
  const t=[...document.querySelectorAll('[role=tab]')].find(e=>e.textContent.trim()==='History');
  const r=t.getBoundingClientRect();
  const opts={bubbles:true,cancelable:true,clientX:r.x+r.width/2,clientY:r.y+r.height/2,button:0,pointerId:1,pointerType:'mouse',isPrimary:true};
  t.dispatchEvent(new PointerEvent('pointerdown',opts));
  t.dispatchEvent(new MouseEvent('mousedown',opts));
  t.dispatchEvent(new PointerEvent('pointerup',opts));
  t.dispatchEvent(new MouseEvent('mouseup',opts));
  t.dispatchEvent(new MouseEvent('click',opts));
  return 'selected='+t.getAttribute('aria-selected');
})()" 2>&1 | tail -1
sleep 1
agent-browser eval "(() => { const p=[...document.querySelectorAll('[role=tabpanel]')].find(e=>!e.hidden); return p? p.innerText.slice(0,500):'none'; })()" 2>&1 | tail -8
